from pathlib import Path
import pandas as pd,numpy as np,json,hashlib
B=Path(__file__).resolve().parents[1];ROOT=B.parents[1];A=B/'audit';R=B/'results';A.mkdir(exist_ok=True);R.mkdir(exist_ok=True)
f=ROOT/'subprojects/original-hybird-extended-oct-2026/data/final_news_v3/NEWS_ARTICLES_FINAL_CALCULATED.csv';d=pd.read_csv(f);d['text_key']=d.headline.fillna('').str.lower().str.replace(r'\s+',' ',regex=True).str.strip();u=d[d.text_key.ne('')].drop_duplicates('text_key');random=u.sample(n=240,random_state=2026).copy();random['sampling_stratum']='representative_random';rem=u.drop(random.index);enriched=[]
patterns={'court':r'court|lawsuit|judge|ruling','regulatory':r'regulat|\bsec\b|tariff','listing':r'listing|listed|delist','partnership':r'partner|collaborat','macro':r'fed\b|inflation|interest rate|trump','general_crypto':r'bitcoin|ethereum|crypto'}
for j,(label,pat) in enumerate(patterns.items()):
 pool=rem[rem.headline.str.contains(pat,case=False,na=False,regex=True)]
 if label=='general_crypto':pool=pool[~pool.headline.str.contains(r'\bxrp\b|ripple|hedera|\bhbar\b',case=False,na=False,regex=True)]
 s=pool.sample(n=min(10,len(pool)),random_state=2026+j);s=s.copy();s['sampling_stratum']='enriched_'+label;enriched.append(s);rem=rem.drop(s.index)
sample=pd.concat([random]+enriched).reset_index(drop=True);assert len(sample)==300;sample['audit_id']=[f'A{i:04d}' for i in range(1,301)];sample.to_csv(A/'GPT4O_ANNOTATION_AUDIT.csv',index=False)
fields=['sentiment','stance_xrp','uncertainty','event_type','reg_access_flag','surprise_flag','xrp_specificity'];blinded=sample[['audit_id','headline','article_url','published_at_utc']].sample(frac=1,random_state=801).reset_index(drop=True)
for role in ['reviewer_1','reviewer_2']:
 b=blinded.copy()
 for col in fields+['insufficient_information','evidence_quote','reviewer_notes']:b[col]=''
 b.to_csv(A/f'BLINDED_{role}.csv',index=False)
labels=pd.concat([pd.DataFrame({'audit_id':sample.audit_id,'reviewer':role,**{f:['']*300 for f in fields+['insufficient_information','notes']}}) for role in ['reviewer_1','reviewer_2']]);labels.to_csv(A/'GPT4O_HUMAN_LABELS.csv',index=False)
score_cols=[c for c in d if c.endswith('_contribution')];expected=d[score_cols].sum(axis=1);audit=pd.DataFrame({'record_id':d.record_id,'saved_impact':d.impact_score,'component_sum':expected,'absolute_error':abs(d.impact_score-expected),'followers_defaulted':d.followers_defaulted,'engagement_defaulted':d.engagement_defaulted,'regime_alignment_zero':d.regime_align.eq(0),'first_availability_verified':d.first_public_availability_verified,'headline_duplicate':d.text_key.duplicated(False)});audit.to_csv(R/'SENTIMENT_IMPACT_SCORE_AUDIT.csv',index=False)
pd.DataFrame({'field':fields,'status':'pending_two_independent_human_labels','n_human_compared':0}).to_csv(R/'GPT4O_FIELD_ACCURACY.csv',index=False)
repeat=random.sample(n=100,random_state=104).copy();repeat[['record_id','headline','article_url','annotation_origin']+fields].to_csv(A/'REPEATABILITY_FIXED_100.csv',index=False);pd.DataFrame({'record_id':repeat.record_id,'status':'not_run_requires_verified_original_settings_and_API_cost_review'}).to_csv(R/'GPT4O_REPEATABILITY_RESULTS.csv',index=False)
(A/'ANNOTATION_GUIDE.md').write_text('''# Independent blinded article review\n\nTwo human reviewers must work separately using their own blinded CSV. Do not open GPT4O_ANNOTATION_AUDIT.csv or communicate labels before submission. Do not look at subsequent prices. Label only the supplied headline and contemporaneous article text when recoverable. Mark insufficient information rather than inventing details. Record evidence and the text version used. The current package contains headlines, not guaranteed full original text.\n\nSentiment: -1 strongly negative, 0 neutral, +1 strongly positive overall crypto-market tone. XRP stance: -1 negative implication for XRP, 0 no clear direction, +1 positive. Uncertainty: 0 explicit settled claim, 1 entirely uncertain or speculative; separate uncertainty from polarity. XRP specificity: 0 unrelated to XRP, 1 specifically about XRP, intermediate for partial focus. Regulatory access: binary 1 for explicit change to regulatory access or legal permission, otherwise 0; unknown if evidence insufficient. Surprise: mark unknown unless the text itself supports an unexpected event; do not infer surprise from subsequent returns. Event type: select the original category or categories supported by text (court ruling, regulatory event, listing, delisting, partnership, custody ETF, hack outage, executive comment, influencer tweet, macro event, general article, governance, speculation, survey). Preserve multi-label events; do not impose a ranking.\n\nExample: a headline stating a court dismissed an XRP claim supports court ruling and high XRP specificity; it does not alone prove market surprise or exact sentiment magnitude. A Bitcoin-only article generally has low XRP specificity; do not automatically assign positive XRP stance. Numeric examples are guidance, not reference answers.\n\nAfter both reviewers submit, preserve their original files. An adjudicator records disagreement resolution in a separate file with rationale. Compute categorical confusion matrices, field-specific denominators, kappa, continuous-score MAE and agreement separately for representative and enriched samples. Unknowns must be reported and excluded transparently, never silently converted to zero.\n''')
s={'archive_rows':len(d),'distinct_headlines':len(u),'sample_n':len(sample),'representative_n':240,'enriched_n':60,'seed':2026,'source_sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'annotation_origin_counts':d.annotation_origin.value_counts(dropna=False).to_dict(),'component_sum_max_error':float(abs(expected-d.impact_score).max()),'human_labels_status':'awaiting two independent reviewers','original_100_audit_status':'not located in initial filename and text search; original accuracy claims unverified','full_text_limitation':'Available archive stores headlines; original article body and original API metadata require provenance recovery','no_paid_API_calls':True}
(B/'STATUS.json').write_text(json.dumps(s,indent=2));print(json.dumps(s,indent=2))
